#!/usr/bin/env bash
# Generated by ClickStarDeploy. Do not edit: it is rewritten on every apply.
set -euo pipefail
: "${APP_DIR:?}" "${RELEASE_DIR:?}" "${APP_PORT:?}" "${DOMAIN:?}" "${APP_SLUG:?}"
SHARED_DIR="${SHARED_DIR:-$APP_DIR/shared}"
# A cancelled CI job ("Dừng") or a dropped SSH session must not stop a release halfway (nginx
# switched, old instance still up): ignore the hang-up and keep a copy of the output on the server
# for when nobody is listening any more.
trap '' HUP PIPE
if tee -p /dev/null </dev/null >/dev/null 2>&1; then
  : > "$APP_DIR/.release.log" 2>/dev/null && exec > >(tee -p -a "$APP_DIR/.release.log") 2>&1
fi
CONF="$RELEASE_DIR/.autodeploy/service.env"
SVC=0; SVC_WORKDIR=""; SVC_START=""; HEALTH_PATH="/"; PUBLIC_PATH="/"
[ -f "$CONF" ] && . "$CONF"
ROOT=0; [ "$(id -u)" = 0 ] && ROOT=1
S() { if [ $ROOT = 1 ]; then "$@"; else sudo -n "$@"; fi; }
say() { echo "==> $*"; }
code_of() { curl -s -o /dev/null -m 8 -w '%{http_code}' "$@" 2>/dev/null || true; }
switch_current() { ln -sfn "$RELEASE_DIR" "$APP_DIR/current.tmp" && mv -Tf "$APP_DIR/current.tmp" "$APP_DIR/current"; }
reload_nginx() { S nginx -t >/dev/null 2>&1 && S systemctl reload nginx; }

# Same-origin CSS/JS/images the page loads: a stray process can answer the page with 200 while
# every asset fails. $1 = origin, $2 = page path, $3 = strict (also 4xx on .js/.css), rest = curl
# options. Prints the broken ones and fails when there are any.
asset_paths() { # $1 = origin, $2 = page path, rest = curl options
  local origin=$1 page=$2
  shift 2
  curl -s -L -m 10 "$@" "$origin$page" 2>/dev/null | head -c 500000 | grep -oiE "(src|href)=[\"'](/[^/\"'#[:space:]][^\"'#[:space:]]*)" | sed -E "s/^[^=]*=[\"']//" |
    grep -iE '\.(m?js|css|png|jpe?g|gif|svg|webp|avif|ico|woff2?|ttf)(\?|$)|^/(_next|_nuxt|assets|static|build|dist)/' |
    sed 's/&amp;/\&/g' | awk '!s[$0]++' | head -n 12 || true
}
broken_assets() {
  local origin=$1 page=$2 strict=$3 bad=0 p c
  shift 3
  for p in $(asset_paths "$origin" "$page" "$@"); do
    c=$(code_of "$@" "$origin$p")
    case "$c" in
      5*|000) echo "  $p → HTTP $c"; bad=1 ;;
      4*) if [ "$strict" = 1 ]; then case "${p%%\?*}" in *.js|*.mjs|*.css) echo "  $p → HTTP $c"; bad=1 ;; esac; fi ;;
    esac
  done
  return $bad
}

# The public site must serve real content: 2xx only (a redirect, 403 or 404 is a failure), and
# the files it loads must work. Ask the http vhost first; follow to https only when it redirects
# there (without a certificate an https request would land on another site's server block).
public_ok() {
  local c origin opts i
  # nginx reloads gracefully: for a few seconds old workers still send requests to the previous
  # target, so the page can come from one build and its JS/CSS from the other (404s). Before
  # judging, wait until nginx answers (no 502/503/504) with the page of the new build: the same
  # files as on the new port ($EXPECT_ASSETS, blue-green only), 3 times in a row so no old worker
  # is still taking requests.
  local same=0
  for i in $(seq 1 40); do
    origin="http://127.0.0.1"; opts=(-H "Host: $DOMAIN")
    c=$(code_of "${opts[@]}" "$origin$PUBLIC_PATH")
    case "$c" in 301|302|307|308) origin="https://$DOMAIN"; opts=(-k --resolve "$DOMAIN:443:127.0.0.1"); c=$(code_of "${opts[@]}" "$origin$PUBLIC_PATH") ;; esac
    case "$c" in
      502|503|504|000) same=0 ;;
      2*)
        [ -z "${EXPECT_ASSETS:-}" ] && break
        if [ "$(asset_paths "$origin" "$PUBLIC_PATH" "${opts[@]}")" = "$EXPECT_ASSETS" ]; then
          same=$((same + 1)); [ $same -ge 3 ] && break; continue
        fi
        same=0 ;;
      *) break ;;
    esac
    sleep 1
  done
  case "$c" in 2*) ;; *) echo "✖ Website trả lời HTTP $c ở $PUBLIC_PATH (cần 2xx)"; return 1 ;; esac
  local bad
  if ! bad=$(broken_assets "$origin" "$PUBLIC_PATH" 1 "${opts[@]}"); then
    echo "✖ Website trả HTTP $c nhưng file tĩnh của trang bị lỗi:"; echo "$bad"; return 1
  fi
  say "Website trả lời HTTP $c, file tĩnh tải được"
}

if [ "$SVC" = 1 ] && [ -n "$SVC_START" ] && [ $ROOT = 1 ]; then
  # Each instance gets one of five port slots: $APP_PORT + 0/10000/20000/30000/40000. The new
  # release takes the first slot that is neither live nor used by another process, so apps that
  # must keep their ports (even on our slots) are never touched; usually it is A <-> A+10000.
  A=$APP_PORT
  SLOTS="$A $((A + 10000)) $((A + 20000)) $((A + 30000)) $((A + 40000))"
  in_use() { command -v ss >/dev/null && [ -n "$(ss -ltnH "sport = :$1" 2>/dev/null)" ]; }
  # Our instance on port $1 is really serving (a stray process on the port does not count).
  serving() { { systemctl is-active --quiet "$APP_SLUG@$1" || { [ "$1" = "$A" ] && systemctl is-active --quiet "$APP_SLUG.service"; }; } && in_use "$1"; }
  SITE_FILES=""
  for f in "/etc/nginx/sites-available/$APP_SLUG.conf" "/etc/nginx/conf.d/$APP_SLUG.conf" "/etc/nginx/sites-enabled/$APP_SLUG.conf"; do
    [ -e "$f" ] && SITE_FILES="$SITE_FILES $(readlink -f "$f")"
  done
  # Site files named otherwise (after the domain, say) that serve $DOMAIN.
  for f in $(grep -lsE "server_name[^;]*[[:space:]]$(printf '%s' "$DOMAIN" | sed 's/\./\\./g')[[:space:];]" /etc/nginx/sites-enabled/* /etc/nginx/conf.d/*.conf 2>/dev/null || true); do
    case " $SITE_FILES " in *" $(readlink -f "$f") "*) ;; *) SITE_FILES="$SITE_FILES $(readlink -f "$f")" ;; esac
  done
  NGINX_PORT=$([ -n "$SITE_FILES" ] && cat $SITE_FILES 2>/dev/null | grep -oE "(127\.0\.0\.1|localhost):(${SLOTS// /|})([^0-9]|$)" | head -n 1 | grep -oE ':[0-9]+' | tr -d : || true)
  # The live instance: .active-port can be stale (manual fixes, a crashed release), so trust the
  # first slot our unit really serves on, else what nginx points at. A wrong guess here would
  # stop the instance that is serving the site.
  ACTIVE=""
  for P in "$(cat "$APP_DIR/.active-port" 2>/dev/null || true)" "$NGINX_PORT" $SLOTS; do
    case " $SLOTS " in *" $P "*) ;; *) continue ;; esac
    if serving "$P"; then ACTIVE=$P; break; fi
  done
  OLD_ALIVE=1
  if [ -z "$ACTIVE" ]; then
    OLD_ALIVE=0
    ACTIVE=$(cat "$APP_DIR/.active-port" 2>/dev/null || true)
    case " $SLOTS " in *" $ACTIVE "*) ;; *) ACTIVE=${NGINX_PORT:-$A} ;; esac
    say "Bản đang chạy (cổng $ACTIVE) không hoạt động: website đang lỗi, bản mới sẽ thay thế"
  fi
  OLD=$ACTIVE
  owner_of() {
    local pid; pid=$(ss -ltnpH "sport = :$1" 2>/dev/null | grep -oE 'pid=[0-9]+' | head -n 1 | cut -d= -f2)
    [ -n "$pid" ] || { echo "một tiến trình khác"; return; }
    echo "PID $pid ($(ps -o cmd= -p "$pid" 2>/dev/null | cut -c1-60); $(sed -n 's#.*/\([^/]*\.service\)$#\1#p' "/proc/$pid/cgroup" 2>/dev/null | tail -n 1))"
  }
  NEW=""
  for P in $SLOTS; do
    [ "$P" = "$ACTIVE" ] && continue
    [ "$P" -le 65535 ] || continue
    systemctl stop "$APP_SLUG@$P" 2>/dev/null || true # our own idle instance, not serving
    if in_use "$P"; then say "Cổng $P đang được $(owner_of "$P") dùng: giữ nguyên, chọn cổng khác"; continue; fi
    NEW=$P; break
  done
  if [ -z "$NEW" ]; then
    echo "✖ Không còn cổng trống cho bản mới (đã thử $SLOTS, trừ cổng đang chạy $ACTIVE). Website vẫn chạy bản cũ."
    exit 1
  fi
  RUN_USER=$(stat -c %U "$APP_DIR/releases" 2>/dev/null || echo root)

  # Start command in its own file: no quoting games inside the unit. PORT is forced to this
  # instance's port even when .env sets one.
  cat > "$APP_DIR/.start-$NEW.sh" <<EOF
#!/usr/bin/env bash
set -a; [ -f "$SHARED_DIR/.env" ] && . "$SHARED_DIR/.env"; set +a
export PORT=$NEW NODE_ENV=\${NODE_ENV:-production}
cd "$APP_DIR/live-$NEW/$SVC_WORKDIR"
exec $SVC_START
EOF
  chmod 755 "$APP_DIR/.start-$NEW.sh"

  UNIT="/etc/systemd/system/$APP_SLUG@.service"
  TMP=$(mktemp)
  cat > "$TMP" <<EOF
[Unit]
Description=$APP_SLUG (ClickStarDeploy, port %i)
After=network.target

[Service]
Type=simple
User=$RUN_USER
ExecStart=/bin/bash $APP_DIR/.start-%i.sh
Restart=always
RestartSec=3
TimeoutStopSec=20

[Install]
WantedBy=multi-user.target
EOF
  if ! cmp -s "$TMP" "$UNIT"; then install -m 644 "$TMP" "$UNIT"; systemctl daemon-reload; fi
  rm -f "$TMP"

  ln -sfn "$RELEASE_DIR" "$APP_DIR/live-$NEW"
  say "Khởi động bản mới trên cổng $NEW (bản đang chạy vẫn phục vụ khách)"
  systemctl restart "$APP_SLUG@$NEW"
  ok=0; c=000
  for i in $(seq 1 90); do
    # The answer must come from our unit: a crash loop behind a stray listener is a failure.
    if systemctl is-active --quiet "$APP_SLUG@$NEW"; then
      c=$(code_of "http://127.0.0.1:$NEW$HEALTH_PATH")
      case "$c" in 2*|3*) sleep 2; systemctl is-active --quiet "$APP_SLUG@$NEW" && { ok=1; break; } ;; esac
    else
      c="dịch vụ chưa chạy"
    fi
    sleep 1
  done
  if [ $ok != 1 ]; then
    echo "✖ Bản mới không trả lời trên cổng $NEW$HEALTH_PATH (HTTP $c). Website vẫn chạy bản cũ."
    journalctl -u "$APP_SLUG@$NEW" -n 40 --no-pager || true
    systemctl stop "$APP_SLUG@$NEW" || true
    exit 1
  fi
  # Before any traffic moves: the files the page loads must not fail on the new instance (404 is
  # allowed here, nginx may serve those files itself).
  if ! bad=$(broken_assets "http://127.0.0.1:$NEW" "$PUBLIC_PATH" 0 -H "Host: $DOMAIN"); then
    echo "✖ Bản mới trả trang nhưng file tĩnh lỗi trên cổng $NEW. Website vẫn chạy bản cũ."
    echo "$bad"
    journalctl -u "$APP_SLUG@$NEW" -n 30 --no-pager || true
    systemctl stop "$APP_SLUG@$NEW" || true
    exit 1
  fi

  # What the page of this build loads: public_ok waits until nginx serves exactly this.
  EXPECT_ASSETS=$(asset_paths "http://127.0.0.1:$NEW" "$PUBLIC_PATH" -H "Host: $DOMAIN")

  # Point nginx at the new port (the site file may still name the original $APP_PORT).
  # Backups live outside /etc/nginx: a stray copy in sites-enabled/ would be loaded as config.
  BK="$APP_DIR/.nginx-backup"; rm -rf "$BK"; mkdir -p "$BK"; : > "$BK/list"
  declare -A SEEN=()
  for real in $SITE_FILES; do
    [ -n "${SEEN[$real]:-}" ] && continue
    SEEN[$real]=1
    cp -p "$real" "$BK/$(echo "$real" | tr / _)"
    echo "$real" >> "$BK/list"
    sed -i -E "s#(127\.0\.0\.1|localhost):(${SLOTS// /|})([^0-9]|$)#127.0.0.1:$NEW\3#g" "$real"
  done
  if ! reload_nginx; then
    echo "✖ nginx -t lỗi sau khi đổi cổng, khôi phục cấu hình cũ"
    while read -r real; do cp -p "$BK/$(echo "$real" | tr / _)" "$real"; done < "$BK/list"
    systemctl stop "$APP_SLUG@$NEW" || true
    exit 1
  fi
  PREV=$(readlink -f "$APP_DIR/current" 2>/dev/null || true)
  echo "$NEW" > "$APP_DIR/.active-port"
  switch_current
  # Checked through nginx while the previous instance still runs: on failure everything goes back.
  if ! public_ok; then
    if [ "$OLD_ALIVE" != 1 ]; then
      # Going back would point nginx at a dead port: keep the new instance, it answers locally.
      systemctl enable "$APP_SLUG@$NEW" >/dev/null 2>&1 || true
      systemctl disable "$APP_SLUG@$OLD" >/dev/null 2>&1 || true
      echo "✖ Bản cũ đã ngừng chạy nên giữ bản mới trên cổng $NEW (chạy tốt khi gọi trực tiếp), nhưng kiểm tra qua nginx vẫn lỗi."
      exit 1
    fi
    echo "==> Quay lại bản đang chạy trước đó (cổng $OLD)"
    while read -r real; do cp -p "$BK/$(echo "$real" | tr / _)" "$real"; done < "$BK/list"
    reload_nginx || true
    echo "$OLD" > "$APP_DIR/.active-port"
    [ -n "$PREV" ] && [ -d "$PREV" ] && ln -sfn "$PREV" "$APP_DIR/current.tmp" && mv -Tf "$APP_DIR/current.tmp" "$APP_DIR/current"
    systemctl stop "$APP_SLUG@$NEW" || true
    exit 1
  fi
  systemctl enable "$APP_SLUG@$NEW" >/dev/null 2>&1 || true
  say "Đã chuyển nginx sang cổng $NEW, chờ các request cũ xong rồi tắt bản cũ"
  sleep 5
  systemctl disable --now "$APP_SLUG@$OLD" >/dev/null 2>&1 || true
  # Older single-unit setup (before blue-green): retire it once.
  if systemctl cat "$APP_SLUG.service" >/dev/null 2>&1; then systemctl disable --now "$APP_SLUG.service" >/dev/null 2>&1 || true; fi
else
  PREV=$(readlink -f "$APP_DIR/current" 2>/dev/null || true)
  apply_release() {
    if [ "$SVC" = 1 ] && systemctl cat "$APP_SLUG.service" >/dev/null 2>&1; then
      say "Khởi động lại $APP_SLUG"
      S systemctl restart "$APP_SLUG"
    fi
    for svc in $(systemctl list-units --type=service --state=running --no-legend 'php*-fpm*' 2>/dev/null | awk '{print $1}'); do S systemctl reload "$svc" || true; done
    reload_nginx || true
  }
  switch_current
  apply_release
  if ! public_ok; then
    if [ -n "$PREV" ] && [ -d "$PREV" ] && [ "$PREV" != "$(readlink -f "$RELEASE_DIR")" ]; then
      echo "==> Quay lại bản trước: $(basename "$PREV")"
      ln -sfn "$PREV" "$APP_DIR/current.tmp" && mv -Tf "$APP_DIR/current.tmp" "$APP_DIR/current"
      apply_release
    fi
    exit 1
  fi
fi
say "Deploy xong"
